"use client";

import { cn } from "@/lib/utils";

interface SegmentedControlProps {
    options: { label: string; value: string }[];
    value: string;
    onChange: (value: string) => void;
    label?: string;
    className?: string;
}

export default function SegmentedControl({ options, value, onChange, label, className }: SegmentedControlProps) {
    return (
        <div className={cn("space-y-2", className)}>
            {label && (
                <label className="text-[11px] font-black text-on-surface-variant uppercase tracking-widest px-1">
                    {label}
                </label>
            )}
            <div className="flex p-1.5 bg-surface-variant/20 dark:bg-slate-800/80 rounded-full border border-outline/5 self-start shadow-sm">
                {options.map((option) => {
                    const isActive = value === option.value;
                    return (
                        <button
                            key={option.value}
                            type="button"
                            onClick={() => onChange(option.value)}
                            className={cn(
                                "px-6 py-2.5 text-[10px] font-black uppercase tracking-[0.15em] rounded-full transition-all duration-300 relative",
                                isActive
                                    ? "bg-primary text-on-primary shadow-m3-1 scale-100"
                                    : "text-on-surface-variant hover:text-on-surface hover:bg-surface-variant/30 scale-100 px-5"
                            )}
                        >
                            {option.label}
                        </button>
                    );
                })}
            </div>
        </div>
    );
}
